#include <cuda_runtime.h>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <chrono>
#include <algorithm>
#define main historical_main
#include "../convolution1D-cuda/main.cu"
#undef main
constexpr int N_STUDY=2048, STRIDE_STUDY=2064, OUTPUT_GROUP=2064*15, GUARD_STUDY=-12345;
struct InputCase{void*data;std::vector<int64_t>cpu;int dtype;};
struct Group{int input,mw,dtype;void*out;std::vector<unsigned char>maskbytes;std::vector<int64_t>mask;std::vector<double>expected;};
int bytes_for(int t){return t==0?8:t==1?4:2;}
double decode(uint64_t word,int t){if(t==0){double x;memcpy(&x,&word,8);return x;}if(t==1){float x;uint32_t w=word;memcpy(&x,&w,4);return x;}int16_t x;uint16_t w=word;memcpy(&x,&w,2);return x;}
template<class T>void update_mask(const Group&g){GPU_CHECK(cudaMemcpyToSymbol(mask<T>,g.maskbytes.data(),g.mw*sizeof(T)));std::vector<unsigned char>check(g.mw*sizeof(T));GPU_CHECK(cudaMemcpyFromSymbol(check.data(),mask<T>,check.size()));if(check!=g.maskbytes)exit(9);}
template<class T>void reset_output(const Group&g){std::vector<T>guard(OUTPUT_GROUP,T(GUARD_STUDY));GPU_CHECK(cudaMemcpy(g.out,guard.data(),guard.size()*sizeof(T),cudaMemcpyHostToDevice));}
void prepare(const Group&g){if(g.dtype==0){update_mask<double>(g);reset_output<double>(g);}else if(g.dtype==1){update_mask<float>(g);reset_output<float>(g);}else{update_mask<int16_t>(g);reset_output<int16_t>(g);}GPU_CHECK(cudaDeviceSynchronize());}
template<class T>void launch_typed(const Group&g,const InputCase&input){for(int mode=0;mode<3;mode++)for(int bi=0,bt=64;bi<5;bi++,bt*=2){T*out=(T*)g.out+(mode*5+bi)*STRIDE_STUDY+8;const T*in=(const T*)input.data;if(mode==0)conv1d<<<N_STUDY/bt,bt>>>(in,out,N_STUDY,g.mw);else if(mode==1)conv1d_tiled<<<N_STUDY/bt,bt,(bt+9)*sizeof(T)>>>(in,out,N_STUDY,g.mw);else conv1d_tiled_caching<<<N_STUDY/bt,bt,bt*sizeof(T)>>>(in,out,N_STUDY,g.mw);}}
void launch(const Group&g,const InputCase&input){if(g.dtype==0)launch_typed<double>(g,input);else if(g.dtype==1)launch_typed<float>(g,input);else launch_typed<int16_t>(g,input);}
template<class T>void capture(const Group&g,std::vector<uint64_t>&art,bool&ok,double&err){std::vector<T>host(OUTPUT_GROUP);GPU_CHECK(cudaMemcpy(host.data(),g.out,host.size()*sizeof(T),cudaMemcpyDeviceToHost));for(int i=0;i<OUTPUT_GROUP;i++){double x=double(host[i]),ref=g.expected[i];uint64_t word,wref;memcpy(&word,&x,8);memcpy(&wref,&ref,8);ok&=word==wref;err=std::max(err,fabs(x-ref));art.push_back(word);}}
int main(){std::vector<uint64_t>prefix(12432);FILE*f=fopen("/home/imo/HeCBench_julia/src/convolution1D-julia/fixture.bin","rb");if(!f||fread(prefix.data(),8,prefix.size(),f)!=prefix.size())return 4;fclose(f);std::vector<InputCase>inputs;size_t offset=0;for(int fixture=0;fixture<2;fixture++)for(int t=0;t<3;t++){InputCase c;c.dtype=t;int bytes=bytes_for(t);std::vector<unsigned char>raw(N_STUDY*bytes);for(int i=0;i<N_STUDY;i++){memcpy(raw.data()+i*bytes,&prefix[offset+i],bytes);double x=decode(prefix[offset+i],t);int64_t integer=int64_t(x);if(double(integer)!=x)return 5;c.cpu.push_back(integer);}GPU_CHECK(cudaMalloc(&c.data,raw.size()));GPU_CHECK(cudaMemcpy(c.data,raw.data(),raw.size(),cudaMemcpyHostToDevice));std::vector<unsigned char>roundtrip(raw.size());GPU_CHECK(cudaMemcpy(roundtrip.data(),c.data,raw.size(),cudaMemcpyDeviceToHost));if(roundtrip!=raw)return 6;inputs.push_back(c);offset+=N_STUDY;}
srand(123);for(int i=0;i<N_STUDY;i++)if(inputs[0].cpu[i]!=rand()%256)return 8;
std::vector<Group>groups;for(int fixture=0;fixture<2;fixture++)for(int mw=3;mw<=9;mw+=2)for(int t=0;t<3;t++){Group g;g.input=fixture*3+t;g.mw=mw;g.dtype=t;int bytes=bytes_for(t);g.maskbytes.resize(mw*bytes);for(int j=0;j<mw;j++){memcpy(g.maskbytes.data()+j*bytes,&prefix[offset+j],bytes);double x=decode(prefix[offset+j],t);g.mask.push_back(int64_t(x));if(double(g.mask.back())!=x)return 10;}offset+=mw;g.expected.assign(OUTPUT_GROUP,double(GUARD_STUDY));int64_t maxinput=0,sumabs=0;for(int64_t x:inputs[g.input].cpu)maxinput=std::max(maxinput,std::abs(x));for(int64_t x:g.mask)sumabs+=std::abs(x);if(maxinput*sumabs>=32767)return 11;for(int i=0;i<N_STUDY;i++){int64_t acc=0;for(int j=0;j<mw;j++){int idx=i-mw/2+j;if(idx>=0&&idx<N_STUDY)acc+=inputs[g.input].cpu[idx]*g.mask[j];}for(int path=0;path<15;path++)g.expected[path*STRIDE_STUDY+8+i]=double(acc);}GPU_CHECK(cudaMalloc(&g.out,OUTPUT_GROUP*bytes));groups.push_back(g);}if(offset!=prefix.size()||groups.size()!=24)return 12;
for(auto&g:groups){prepare(g);launch(g,inputs[g.input]);GPU_CHECK(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){double seconds=0,err=0;bool ok=true;std::vector<uint64_t>art=prefix;for(auto&g:groups){prepare(g);auto start=std::chrono::steady_clock::now();for(int rep=0;rep<3;rep++)launch(g,inputs[g.input]);GPU_CHECK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;if(g.dtype==0)capture<double>(g,art,ok,err);else if(g.dtype==1)capture<float>(g,art,ok,err);else capture<int16_t>(g,art,ok,err);}if(art.size()!=755472)return 13;const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*out=fopen(path.c_str(),"wb");fwrite(art.data(),8,art.size(),out);fclose(out);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":743040,\"max_abs_error\":%.17g,\"max_rel_error\":0,\"timing_region\":\"sum24group_15kernelpath_batches_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":755472,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",err,path.c_str());}for(auto&i:inputs)cudaFree(i.data);for(auto&g:groups)cudaFree(g.out);}
